#!/usr/bin/env node
/**
 * Restores `src/convex/_generated/` from the committed snapshot in
 * `src/deploy/convex-bindings/` when the folder is missing.
 *
 * WHY THIS EXISTS
 * The Convex bindings are consumed twice:
 *   1. at build time — `tsc -b` typechecks every file under `src/convex/`, which
 *      imports `./_generated/server`, and
 *   2. at runtime — 17 components import `@/convex/_generated/api`.
 * `src/convex/_generated` is regenerated by the Convex CLI, which needs deploy
 * credentials or a running `.env.local`. A plain static host (Vercel) has
 * neither, so on a fresh checkout the build failed with 346 errors beginning
 * `Cannot find module './_generated/server'`.
 *
 * WHY IT LIVES UNDER `src/deploy/`
 * `src/**` is the only path guaranteed to reach the host, and this script plus
 * its snapshot have to be in the checkout for the restore to be possible at
 * all. It is a `.mjs` file (not `.ts`) so plain `node` can run it during
 * `postinstall`, before any toolchain is available, and `src/deploy` is excluded
 * from `tsconfig.app.json` so the snapshot's `.d.ts` files are never typechecked
 * from that location.
 *
 * SAFETY
 * The snapshot is only ever a byte-for-byte copy of real `convex codegen`
 * output, and this script never overwrites an existing folder. Local development
 * is therefore untouched: `npx convex dev` keeps writing live bindings there.
 * Refresh the snapshot after adding or removing a Convex function with:
 *   bun run convex:bindings:snapshot
 */
import { copyFileSync, existsSync, mkdirSync, readdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const projectRoot = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
const target = resolve(projectRoot, "src/convex/_generated");
const snapshot = resolve(projectRoot, "src/deploy/convex-bindings");

// Documentation only — never copied into the bindings folder.
const SKIP = new Set(["README.md"]);

// `--snapshot` inverts the direction: it refreshes the committed snapshot from
// freshly generated bindings, which is what `bun run convex:bindings:snapshot`
// uses after the Convex CLI has rewritten `src/convex/_generated`.
if (process.argv.includes("--snapshot")) {
  if (!existsSync(target)) {
    console.error(
      `[convex-bindings] Cannot snapshot: ${target} does not exist yet. Run \`bunx convex codegen\` first.`,
    );
    process.exit(1);
  }
  const files = readdirSync(target).filter((file) => !SKIP.has(file));
  mkdirSync(snapshot, { recursive: true });
  for (const file of files) {
    copyFileSync(resolve(target, file), resolve(snapshot, file));
  }
  console.log(
    `[convex-bindings] Snapshot refreshed (${files.length} files) from src/convex/_generated.`,
  );
  process.exit(0);
}

if (existsSync(target)) {
  console.log(
    "[convex-bindings] src/convex/_generated already exists — leaving it untouched.",
  );
  process.exit(0);
}

if (!existsSync(snapshot)) {
  console.error(
    "[convex-bindings] No bindings available.\n" +
      `  Missing generated folder: ${target}\n` +
      `  Missing snapshot folder:  ${snapshot}`,
  );
  process.exit(1);
}

const files = readdirSync(snapshot).filter((file) => !SKIP.has(file));
mkdirSync(target, { recursive: true });
for (const file of files) {
  copyFileSync(resolve(snapshot, file), resolve(target, file));
}
console.log(
  `[convex-bindings] Restored src/convex/_generated (${files.length} files) from src/deploy/convex-bindings.`,
);
